import React, { useState, useEffect } from 'react';
import {
    Grid,
    Paper,
    Typography,
    Box,
    Card,
    CardContent,
    CircularProgress,
    Alert,
    Divider,
    List,
    ListItem,
    ListItemText,
    ListItemAvatar,
    Avatar,
    Button,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow
} from '@mui/material';
import {
    People,
    CheckCircle,
    Cancel,
    Pending,
    Today,
    TrendingUp,
    Warning
} from '@mui/icons-material';
import { dashboardService, attendanceService, leaveService } from '../../services/api';

const HRDashboard = () => {
    const [dashboardData, setDashboardData] = useState(null);
    const [attendanceSummary, setAttendanceSummary] = useState(null);
    const [pendingLeaves, setPendingLeaves] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');

    useEffect(() => {
        fetchAllData();
    }, []);

    const fetchAllData = async () => {
        try {
            setLoading(true);
            const [dashboardRes, summaryRes, leavesRes] = await Promise.all([
                dashboardService.getHRDashboard(),
                attendanceService.getSummary(),
                leaveService.getAllLeaves({ status: 'pending' })
            ]);
            setDashboardData(dashboardRes.data.data);
            setAttendanceSummary(summaryRes.data.data);
            setPendingLeaves(leavesRes.data.leaves || []);
            setError('');
        } catch (err) {
            setError('Failed to load dashboard data');
        } finally {
            setLoading(false);
        }
    };

    const handleLeaveAction = async (leaveId, status) => {
        try {
            await leaveService.updateStatus(leaveId, { status, remarks: 'Processed by HR' });
            await fetchAllData();
            alert(`✅ Leave ${status} successfully!`);
        } catch (err) {
            alert(err.response?.data?.message || 'Failed to process leave');
        }
    };

    if (loading) {
        return (
            <Box display="flex" justifyContent="center" alignItems="center" minHeight="60vh">
                <CircularProgress />
            </Box>
        );
    }

    if (error) {
        return (
            <Alert severity="error" sx={{ mt: 2 }}>
                {error}
            </Alert>
        );
    }

    const { totalEmployees, todayAttendance, pendingLeaves: pendingLeavesCount, departmentStats } = dashboardData || {};

    return (
        <Box>
            <Typography variant="h4" gutterBottom>
                📊 HR Dashboard
            </Typography>
            <Typography variant="subtitle1" color="textSecondary" gutterBottom>
                Company Overview & Attendance Management
            </Typography>

            <Grid container spacing={3} sx={{ mb: 3 }}>
                <Grid item xs={12} sm={6} md={3}>
                    <Card>
                        <CardContent>
                            <Box display="flex" alignItems="center" justifyContent="space-between">
                                <Typography color="textSecondary" gutterBottom>
                                    Total Employees
                                </Typography>
                                <People color="primary" />
                            </Box>
                            <Typography variant="h5">
                                {totalEmployees || 0}
                            </Typography>
                        </CardContent>
                    </Card>
                </Grid>

                <Grid item xs={12} sm={6} md={3}>
                    <Card>
                        <CardContent>
                            <Box display="flex" alignItems="center" justifyContent="space-between">
                                <Typography color="textSecondary" gutterBottom>
                                    Today's Attendance
                                </Typography>
                                <Today color="success" />
                            </Box>
                            <Typography variant="h5">
                                {todayAttendance?.checkedIn || 0}
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                                Present: {todayAttendance?.present || 0} | Late: {todayAttendance?.late || 0}
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                                Rate: {todayAttendance?.attendanceRate || 0}%
                            </Typography>
                        </CardContent>
                    </Card>
                </Grid>

                <Grid item xs={12} sm={6} md={3}>
                    <Card>
                        <CardContent>
                            <Box display="flex" alignItems="center" justifyContent="space-between">
                                <Typography color="textSecondary" gutterBottom>
                                    Pending Leaves
                                </Typography>
                                <Pending color="warning" />
                            </Box>
                            <Typography variant="h5">
                                {pendingLeavesCount || 0}
                            </Typography>
                            <Button 
                                size="small" 
                                variant="outlined" 
                                onClick={() => document.getElementById('pending-leaves-section').scrollIntoView()}
                            >
                                Review Now
                            </Button>
                        </CardContent>
                    </Card>
                </Grid>

                <Grid item xs={12} sm={6} md={3}>
                    <Card>
                        <CardContent>
                            <Box display="flex" alignItems="center" justifyContent="space-between">
                                <Typography color="textSecondary" gutterBottom>
                                    Departments
                                </Typography>
                                <TrendingUp color="info" />
                            </Box>
                            <Typography variant="h5">
                                {departmentStats?.length || 0}
                            </Typography>
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>

            <Paper sx={{ p: 3, mb: 3 }}>
                <Typography variant="h6" gutterBottom>
                    📋 Today's Attendance Summary
                </Typography>
                <Divider sx={{ mb: 2 }} />
                <Grid container spacing={2}>
                    <Grid item xs={4}>
                        <Box textAlign="center">
                            <CheckCircle color="success" />
                            <Typography variant="h6">{attendanceSummary?.present || 0}</Typography>
                            <Typography variant="caption">Present</Typography>
                        </Box>
                    </Grid>
                    <Grid item xs={4}>
                        <Box textAlign="center">
                            <Warning color="warning" />
                            <Typography variant="h6">{attendanceSummary?.late || 0}</Typography>
                            <Typography variant="caption">Late</Typography>
                        </Box>
                    </Grid>
                    <Grid item xs={4}>
                        <Box textAlign="center">
                            <Cancel color="error" />
                            <Typography variant="h6">{attendanceSummary?.absent || 0}</Typography>
                            <Typography variant="caption">Absent</Typography>
                        </Box>
                    </Grid>
                </Grid>
                <Box sx={{ mt: 2 }}>
                    <Typography variant="body2" color="textSecondary">
                        Total Employees: {attendanceSummary?.totalEmployees || 0}
                    </Typography>
                    <Typography variant="body2" color="textSecondary">
                        Attendance Rate: {attendanceSummary?.attendanceRate || 0}%
                    </Typography>
                </Box>
            </Paper>

            {departmentStats && departmentStats.length > 0 && (
                <Paper sx={{ p: 3, mb: 3 }}>
                    <Typography variant="h6" gutterBottom>
                        🏢 Department-wise Employee Distribution
                    </Typography>
                    <Divider sx={{ mb: 2 }} />
                    <TableContainer>
                        <Table>
                            <TableHead>
                                <TableRow>
                                    <TableCell>Department</TableCell>
                                    <TableCell align="right">Employees</TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {departmentStats.map((dept) => (
                                    <TableRow key={dept._id}>
                                        <TableCell>{dept._id}</TableCell>
                                        <TableCell align="right">{dept.count}</TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    </TableContainer>
                </Paper>
            )}

            <Paper sx={{ p: 3, mb: 3 }} id="pending-leaves-section">
                <Typography variant="h6" gutterBottom>
                    📝 Pending Leave Requests ({pendingLeaves.length})
                </Typography>
                <Divider sx={{ mb: 2 }} />
                {pendingLeaves.length === 0 ? (
                    <Typography color="textSecondary">No pending leave requests</Typography>
                ) : (
                    <List>
                        {pendingLeaves.map((leave) => (
                            <ListItem key={leave._id} divider>
                                <ListItemAvatar>
                                    <Avatar sx={{ bgcolor: 'warning.main' }}>
                                        <Pending />
                                    </Avatar>
                                </ListItemAvatar>
                                <ListItemText
                                    primary={`${leave.user?.name || 'Unknown'} - ${leave.type?.toUpperCase() || 'Leave'}`}
                                    secondary={
                                        <>
                                            <Typography variant="body2" component="span">
                                                {leave.user?.department} | {leave.user?.employeeId}
                                            </Typography>
                                            <br />
                                            <Typography variant="body2" component="span" color="textSecondary">
                                                {new Date(leave.startDate).toLocaleDateString()} - {new Date(leave.endDate).toLocaleDateString()}
                                                {' | '}{leave.totalDays} days
                                            </Typography>
                                            <br />
                                            <Typography variant="body2" component="span">
                                                Reason: {leave.reason}
                                            </Typography>
                                        </>
                                    }
                                />
                                <Box sx={{ display: 'flex', gap: 1 }}>
                                    <Button 
                                        variant="contained" 
                                        color="success" 
                                        size="small"
                                        onClick={() => handleLeaveAction(leave._id, 'approved')}
                                    >
                                        Approve
                                    </Button>
                                    <Button 
                                        variant="contained" 
                                        color="error" 
                                        size="small"
                                        onClick={() => handleLeaveAction(leave._id, 'rejected')}
                                    >
                                        Reject
                                    </Button>
                                </Box>
                            </ListItem>
                        ))}
                    </List>
                )}
            </Paper>
        </Box>
    );
};

export default HRDashboard;
